INSERT INTO newtech_project (id, project_name, project_type, dept_id, dept_name, applicant_id, applicant_name, project_leader, team_members, background, objective, tech_plan, expected_benefit, budget, start_date, end_date, ethics_required, ethics_status, ethics_reviewer, ethics_opinion, ethics_review_date, status, approver, approval_opinion, approval_history, apply_date) SELECT 1, '温针灸治疗膝骨关节炎临床研究', 'NEW_TECH', 1, '中医内科', 1, '陈国强', '陈国强', '陈国强、李雅琴', '膝骨关节炎是中老年人常见病，温针灸结合温热与针刺双重作用，临床观察疗效较好，需规范化研究验证', '评价温针灸治疗膝骨关节炎的临床疗效与安全性，形成可推广的中医外治方案', '纳入 120 例膝骨关节炎患者，随机分为温针灸组与常规针刺组，观察 8 周，评价 WOMAC 评分与疼痛视觉模拟评分变化', '为膝骨关节炎提供安全有效的中医外治手段，缩短病程，降低医疗费用', 12.50, '2026-01-05', '2026-12-31', 1, 2, '伦理委员会', '符合伦理要求，同意开展', '2026-11-10', 1, '吴文斌', '同意立项', '伦理审查 伦理委员会：通过（符合伦理要求，同意开展）；医务科 吴文斌：通过（同意立项）', '2026-11-05' FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM (SELECT id FROM newtech_project) AS t WHERE t.id = 1);
