INSERT INTO newtech_project (id, project_name, project_type, dept_id, dept_name, applicant_id, applicant_name, project_leader, team_members, background, objective, tech_plan, expected_benefit, budget, start_date, end_date, ethics_required, ethics_status, ethics_reviewer, ethics_opinion, ethics_review_date, status, approver, approval_opinion, approval_history, apply_date) SELECT 3, '中药熏洗联合手法复位治疗桡骨远端骨折', 'NEW_PROJECT', 3, '骨伤科', 3, '王建军', '王建军', '王建军、张伟', '桡骨远端骨折是骨伤科常见骨折，中药熏洗联合手法复位可促进消肿止痛、加速骨折愈合', '评价中药熏洗联合手法复位治疗桡骨远端骨折的疗效，缩短愈合时间', '纳入 60 例桡骨远端骨折患者，手法复位后中药熏洗治疗 4 周，观察腕关节功能恢复与骨折愈合时间', '推广中医骨伤特色疗法，减少手术率，降低患者负担', 15.00, '2026-03-01', '2026-10-31', 0, 0, NULL, NULL, NULL, 2, '吴文斌', '同意立项', '医务科 吴文斌：通过（同意立项）', '2026-02-20' FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM (SELECT id FROM newtech_project) AS t WHERE t.id = 3);
INSERT INTO newtech_project (id, project_name, project_type, dept_id, dept_name, applicant_id, applicant_name, project_leader, team_members, background, objective, tech_plan, expected_benefit, budget, start_date, end_date, ethics_required, ethics_status, ethics_reviewer, ethics_opinion, ethics_review_date, status, approver, approval_opinion, approval_history, apply_date) SELECT 4, '小儿推拿治疗小儿反复呼吸道感染', 'NEW_PROJECT', 5, '儿科', 5, '孙小红', '孙小红', '孙小红、李雅琴', '小儿反复呼吸道感染发病率高，长期用药副作用大，小儿推拿绿色安全，家长接受度高', '验证小儿推拿减少小儿反复呼吸道感染发作次数的有效性', '纳入 100 例反复呼吸道感染患儿，小儿推拿干预 3 个月，观察发作次数与病程变化', '在儿科门诊推广小儿推拿，减少抗生素使用，提高患儿免疫力', 6.80, '2026-02-01', '2026-09-30', 0, 0, NULL, NULL, NULL, 4, '吴文斌', '同意立项', '医务科 吴文斌：通过（同意立项）', '2026-01-18' FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM (SELECT id FROM newtech_project) AS t WHERE t.id = 4);
INSERT INTO newtech_project (id, project_name, project_type, dept_id, dept_name, applicant_id, applicant_name, project_leader, team_members, background, objective, tech_plan, expected_benefit, budget, start_date, end_date, ethics_required, ethics_status, ethics_reviewer, ethics_opinion, ethics_review_date, status, approver, approval_opinion, approval_history, apply_date) SELECT 5, '中药周期疗法治疗多囊卵巢综合征临床研究', 'NEW_TECH', 4, '妇科', 4, '赵丽华', '赵丽华', '赵丽华、林晓梅', '多囊卵巢综合征是育龄期女性常见内分泌疾病，中药周期疗法按月经周期分期论治，临床有较好应用基础', '评价中药周期疗法改善多囊卵巢综合征患者月经周期与排卵情况的效果', '纳入 90 例多囊卵巢综合征患者，中药周期疗法治疗 3 个月经周期，观察月经恢复与排卵率', '形成中药周期疗法治疗多囊卵巢综合征的诊疗方案，惠及更多患者', 10.00, '2026-11-25', '2027-11-30', 1, 3, '伦理委员会', '知情同意书不完善，需补充风险告知内容', '2026-11-20', 3, '吴文斌', '伦理未通过，请完善知情同意书后重报', '伦理审查 伦理委员会：未通过（知情同意书不完善，需补充风险告知内容）；医务科 吴文斌：驳回（伦理未通过，请完善知情同意书后重报）', '2026-11-12' FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM (SELECT id FROM newtech_project) AS t WHERE t.id = 5);
INSERT INTO newtech_record (id, project_id, record_type, record_date, content, conclusion, recorder) SELECT 1, 3, 'ACCEPTANCE', '2026-11-05', '完成 60 例桡骨远端骨折患者临床观察，腕关节功能优良率 91.7%，骨折平均愈合时间较常规治疗缩短约 2 周', '验收通过，达到预期目标，同意结题', '王建军' FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM (SELECT id FROM newtech_record) AS t WHERE t.id = 1);
INSERT INTO newtech_record (id, project_id, record_type, record_date, content, conclusion, recorder) SELECT 2, 4, 'ACCEPTANCE', '2026-10-12', '完成 100 例反复呼吸道感染患儿干预观察，3 个月内发作次数平均减少 2.1 次，病程缩短，家长满意度 96%', '验收通过，达到预期目标，同意结题', '孙小红' FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM (SELECT id FROM newtech_record) AS t WHERE t.id = 2);
INSERT INTO newtech_record (id, project_id, record_type, record_date, content, conclusion, recorder) SELECT 3, 4, 'PROMOTION', '2026-11-08', '小儿推拿在儿科门诊全面推广，纳入常规诊疗项目，培训科内医师 6 名，累计服务患儿 300 余人次', '推广效果良好，患儿反复呼吸道感染发作次数明显减少，拟向全院推广', '孙小红' FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM (SELECT id FROM newtech_record) AS t WHERE t.id = 3);
