INSERT INTO document (id, title, doc_no, category, version, content, department, drafter, approver, publish_date, effective_date, expiry_date, status, abolish_reason, approval_history, remark) SELECT 1, '三级医师查房制度', 'YW-ZD-2024-001', 'SYSTEM', 'V3.0', '第一章 总则\n第一条 为落实三级医师查房制度，提高医疗质量，保障医疗安全，根据《医疗质量管理办法》及医院实际，制定本制度。\n第二条 三级医师查房是指科主任、主治医师、住院医师三级查房。\n第三条 科主任每周查房不少于 1 次，主治医师每日查房，住院医师每日查房不少于 2 次。\n第四条 查房应有记录，重点记录病情变化、诊疗意见及执行情况。', '医务科', '吴文斌', '陈国强', '2024-01-01', '2024-01-01', '2027-12-31', 1, NULL, '医务科 陈国强：发布（同意）', '医院核心制度之一' FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM (SELECT id FROM document) AS t WHERE t.id = 1);
INSERT INTO document (id, title, doc_no, category, version, content, department, drafter, approver, publish_date, effective_date, expiry_date, status, abolish_reason, approval_history, remark) SELECT 2, '抗菌药物临床应用管理办法', 'YW-ZD-2025-002', 'SYSTEM', 'V2.0', '第一章 总则\n第一条 为规范抗菌药物临床应用，遏制细菌耐药，根据《抗菌药物临床应用管理办法》，结合医院实际制定本办法。\n第二条 抗菌药物实行分级管理：非限制使用级、限制使用级、特殊使用级。\n第三条 特殊使用级抗菌药物须经药事管理与药物治疗学委员会审核、医务科审批后方可使用。', '医务科', '孙小红', '吴文斌', '2025-06-01', '2025-06-01', '2026-12-20', 1, NULL, '医务科 吴文斌：发布（同意）', '2026-12-20 到期，需换版' FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM (SELECT id FROM document) AS t WHERE t.id = 2);
INSERT INTO document (id, title, doc_no, category, version, content, department, drafter, approver, publish_date, effective_date, expiry_date, status, abolish_reason, approval_history, remark) SELECT 3, '病历书写规范', 'YW-GF-2025-001', 'STANDARD', 'V1.0', '第一章 总则\n第一条 病历书写应当客观、真实、准确、及时、完整、规范。\n第二条 住院病历应当在入院后 24 小时内完成，首次病程记录应当在入院后 8 小时内完成。\n第三条 手术记录应当在术后 24 小时内完成，出院记录应当在出院后 24 小时内完成。', '医务科', '林晓梅', '吴文斌', '2025-03-01', '2025-03-01', '2026-11-15', 1, NULL, '医务科 吴文斌：发布（同意）', '已过期，待换版' FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM (SELECT id FROM document) AS t WHERE t.id = 3);
INSERT INTO document (id, title, doc_no, category, version, content, department, drafter, approver, publish_date, effective_date, expiry_date, status, abolish_reason, approval_history, remark) SELECT 4, '门诊接诊流程', 'YW-LC-2025-003', 'PROCESS', 'V1.0', '一、患者挂号后按号序就诊，分诊护士负责维持秩序。\n二、接诊医师应认真询问病史、体格检查，规范书写门诊病历。\n三、需进一步检查者，开具检查申请单并告知注意事项。\n四、复诊患者凭原病历及检查结果按预约时间就诊。', '医务科', '李雅琴', NULL, NULL, NULL, NULL, 0, NULL, NULL, '草稿，待发布审批' FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM (SELECT id FROM document) AS t WHERE t.id = 4);
INSERT INTO document (id, title, doc_no, category, version, content, department, drafter, approver, publish_date, effective_date, expiry_date, status, abolish_reason, approval_history, remark) SELECT 5, '会诊制度', 'YW-ZD-2023-005', 'SYSTEM', 'V1.0', '第一条 会诊分为院内会诊、院外会诊和急会诊。\n第二条 院内会诊由经治医师提出，上级医师同意后填写会诊单。\n第三条 会诊医师应当在 24 小时内完成会诊并书写会诊记录。', '医务科', '吴文斌', '吴文斌', '2023-01-01', '2023-01-01', '2025-12-31', 2, '已被《会诊制度》（V2.0）替代', '医务科 吴文斌：发布（同意）；医务科 吴文斌：作废（已被《会诊制度》（V2.0）替代）', '第 1 版已作废' FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM (SELECT id FROM document) AS t WHERE t.id = 5);
INSERT INTO document (id, title, doc_no, category, version, content, department, drafter, approver, publish_date, effective_date, expiry_date, status, abolish_reason, approval_history, remark) SELECT 6, '医疗质量持续改进工作方案', 'YW-WJ-2026-001', 'FILE', 'V1.0', '一、工作目标：通过 PDCA 循环持续改进医疗质量，年度医疗质量指标达标率 90% 以上。\n二、组织领导：成立医疗质量持续改进工作小组，医务科负责日常工作。\n三、工作内容：每月开展医疗质量检查，每季度召开质量分析会，针对问题制定整改措施并跟踪落实。', '医务科', '吴文斌', '陈国强', '2026-01-01', '2026-01-01', '2027-12-31', 1, NULL, '医务科 陈国强：发布（同意）', '2026 年度质量改进方案' FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM (SELECT id FROM document) AS t WHERE t.id = 6);
INSERT INTO sys_permission (id, parent_id, name, code, type, path, component, sort_order, status) SELECT 20, 0, '政策法规管理', 'policy:list', 2, '/policy', 'policy/PolicyList', 14, 1 FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM (SELECT id FROM sys_permission) AS t WHERE t.id = 20);
INSERT INTO policy (id, title, policy_no, category, level, issuing_authority, version, content, applicable_dept, applicable_personnel, department, drafter, approver, publish_date, effective_date, expiry_date, status, abolish_reason, approval_history, remark) SELECT 1, '中华人民共和国医师法', '主席令第95号', 'LAW', 'NATIONAL', '全国人民代表大会常务委员会', 'V1.0', '第一条 为了保障医师合法权益，规范医师执业行为，加强医师队伍建设，提高医师职业道德和业务素质，保障医疗质量和医疗安全，推进健康中国建设，制定本法。\n第二条 本法所称医师，是指依法取得医师资格，经注册在医疗卫生机构中执业的执业医师和执业助理医师。\n第三条 医师应当坚持人民至上、生命至上，发扬人道主义精神，弘扬敬佑生命、救死扶伤、甘于奉献、大爱无疆的崇高职业精神。', '全院', '全体医师', '医务科', '吴文斌', '陈国强', '2022-03-01', '2022-03-01', NULL, 1, NULL, '医务科 陈国强：发布（同意）', '医师执业基本法，全院医师须学习' FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM (SELECT id FROM policy) AS t WHERE t.id = 1);
INSERT INTO policy (id, title, policy_no, category, level, issuing_authority, version, content, applicable_dept, applicable_personnel, department, drafter, approver, publish_date, effective_date, expiry_date, status, abolish_reason, approval_history, remark) SELECT 2, '医疗质量管理办法', '卫医发〔2016〕28号', 'REGULATION', 'NATIONAL', '国家卫生健康委员会', 'V2.0', '第一条 为加强医疗质量管理，规范医疗服务行为，保障医疗安全，根据《中华人民共和国执业医师法》《医疗机构管理条例》等法律法规，制定本办法。\n第二条 本办法适用于各级各类医疗机构及其医务人员的医疗质量管理活动。\n第三条 医疗机构应当成立医疗质量管理委员会，负责本机构医疗质量管理工作。', '全院', '全体医务人员', '医务科', '孙小红', '吴文斌', '2016-11-01', '2016-11-01', '2026-12-20', 1, NULL, '医务科 吴文斌：发布（同意）', '2026-12-20 到期，需换版' FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM (SELECT id FROM policy) AS t WHERE t.id = 2);
INSERT INTO policy (id, title, policy_no, category, level, issuing_authority, version, content, applicable_dept, applicable_personnel, department, drafter, approver, publish_date, effective_date, expiry_date, status, abolish_reason, approval_history, remark) SELECT 3, '医疗机构管理条例', '国务院令第149号', 'REGULATION', 'NATIONAL', '国务院', 'V1.0', '第一条 为了加强对医疗机构的管理，促进医疗卫生事业的发展，保障公民健康，制定本条例。\n第二条 本条例适用于从事疾病诊断、治疗活动的医院、卫生院、疗养院、门诊部、诊所、卫生所（室）以及急救站等医疗机构。\n第三条 医疗机构以救死扶伤，防病治病，为公民的健康服务为宗旨。', '全院', '全体医务人员', '医务科', '林晓梅', '吴文斌', '1994-09-01', '1994-09-01', '2026-11-15', 1, NULL, '医务科 吴文斌：发布（同意）', '已过期，待换版' FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM (SELECT id FROM policy) AS t WHERE t.id = 3);
INSERT INTO policy (id, title, policy_no, category, level, issuing_authority, version, content, applicable_dept, applicable_personnel, department, drafter, approver, publish_date, effective_date, expiry_date, status, abolish_reason, approval_history, remark) SELECT 4, '中医诊所备案管理暂行办法', '国中医药法监发〔2017〕22号', 'RULE', 'NATIONAL', '国家中医药管理局', 'V1.0', '第一条 为加强中医诊所管理，规范中医诊所执业行为，保障医疗安全，根据《中华人民共和国中医药法》，制定本办法。\n第二条 本办法所称中医诊所，是指在中医药理论指导下，运用中药和针灸、拔罐、推拿等非药物疗法开展诊疗服务，以及中药调剂、汤剂煎煮等中药药事服务的诊所。', '中医内科、针灸科、骨伤科', '全体医师', '医务科', '李雅琴', NULL, NULL, NULL, NULL, 0, NULL, NULL, '草稿，待发布审批' FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM (SELECT id FROM policy) AS t WHERE t.id = 4);
INSERT INTO policy (id, title, policy_no, category, level, issuing_authority, version, content, applicable_dept, applicable_personnel, department, drafter, approver, publish_date, effective_date, expiry_date, status, abolish_reason, approval_history, remark) SELECT 5, '医疗机构药事管理规定', '卫医政发〔2011〕11号', 'RULE', 'NATIONAL', '卫生部', 'V1.0', '第一条 为加强医疗机构药事管理，促进临床合理用药，保障医疗质量和医疗安全，根据《中华人民共和国药品管理法》《医疗机构管理条例》等有关法律法规，制定本规定。\n第二条 本规定适用于各级各类医疗机构的药事管理工作。', '全院', '全体医务人员', '医务科', '吴文斌', '吴文斌', '2011-03-30', '2011-03-30', '2025-12-31', 2, '已被新版《医疗机构药事管理规定》替代', '医务科 吴文斌：发布（同意）；医务科 吴文斌：废止（已被新版《医疗机构药事管理规定》替代）', '第 1 版已废止' FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM (SELECT id FROM policy) AS t WHERE t.id = 5);
INSERT INTO policy (id, title, policy_no, category, level, issuing_authority, version, content, applicable_dept, applicable_personnel, department, drafter, approver, publish_date, effective_date, expiry_date, status, abolish_reason, approval_history, remark) SELECT 6, '广东省医疗纠纷预防与处理办法', '粤府令第286号', 'LOCAL', 'PROVINCIAL', '广东省人民政府', 'V1.0', '第一条 为了预防和妥善处理医疗纠纷，保护医患双方合法权益，维护医疗秩序，根据《医疗纠纷预防和处理条例》等有关法律法规，结合本省实际，制定本办法。\n第二条 本省行政区域内医疗纠纷的预防与处理，适用本办法。\n第三条 医疗纠纷的预防与处理应当坚持预防为主、公平合理、及时便民、依法处理的原则。', '全院', '全体医务人员', '医务科', '吴文斌', '陈国强', '2024-01-01', '2024-01-01', '2027-12-31', 1, NULL, '医务科 陈国强：发布（同意）', '广东省地方性法规' FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM (SELECT id FROM policy) AS t WHERE t.id = 6);
