INSERT INTO sys_permission (id, parent_id, name, code, type, path, component, sort_order, status) SELECT 22, 0, '核心制度管理', 'core-system:list', 2, '/quality/core', 'quality/CoreSystemList', 16, 1 FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM (SELECT id FROM sys_permission) AS t WHERE t.id = 22);
INSERT INTO core_system (id, title, system_no, category, level, issuing_authority, version, content, applicable_dept, applicable_personnel, department, drafter, approver, publish_date, effective_date, expiry_date, status, abolish_reason, approval_history, remark) SELECT 1, '首诊负责制度', 'HX-ZD-2024-001', 'MEDICAL', 'HOSPITAL', '医务科', 'V2.0', '第一条 首诊负责制是指患者到医院就诊，第一位接诊的医师为首诊医师，应对患者的诊疗全过程负责。\n第二条 首诊医师应当认真询问病史、体格检查，规范书写病历，提出诊断意见。\n第三条 首诊医师对诊断尚不明确的患者，应及时请上级医师或相关科室会诊，不得推诿患者。', '全院', '全体医师', '医务科', '吴文斌', '陈国强', '2024-01-01', '2024-01-01', '2027-12-31', 1, NULL, '医务科 陈国强：发布（同意）', '医院核心制度之首，全院医师须学习' FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM (SELECT id FROM core_system) AS t WHERE t.id = 1);
INSERT INTO core_system (id, title, system_no, category, level, issuing_authority, version, content, applicable_dept, applicable_personnel, department, drafter, approver, publish_date, effective_date, expiry_date, status, abolish_reason, approval_history, remark) SELECT 2, '三级医师查房制度', 'HX-ZD-2024-002', 'MEDICAL', 'HOSPITAL', '医务科', 'V3.0', '第一条 三级医师查房是指科主任、主治医师、住院医师三级查房。\n第二条 科主任每周查房不少于 1 次，主治医师每日查房，住院医师每日查房不少于 2 次。\n第三条 查房应有记录，重点记录病情变化、诊疗意见及执行情况。', '全院', '全体医师', '医务科', '孙小红', '吴文斌', '2024-01-01', '2024-01-01', '2026-12-20', 1, NULL, '医务科 吴文斌：发布（同意）', '2026-12-20 到期，需换版' FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM (SELECT id FROM core_system) AS t WHERE t.id = 2);
INSERT INTO core_system (id, title, system_no, category, level, issuing_authority, version, content, applicable_dept, applicable_personnel, department, drafter, approver, publish_date, effective_date, expiry_date, status, abolish_reason, approval_history, remark) SELECT 3, '分级护理制度', 'HX-ZD-2024-003', 'NURSING', 'HOSPITAL', '护理部', 'V1.0', '第一条 分级护理是指根据患者病情轻重缓急和护理级别，实行特级护理、一级护理、二级护理、三级护理。\n第二条 特级护理适用于病情危重、随时可能发生病情变化的患者，需 24 小时专人护理。\n第三条 一级护理适用于病情不稳定或较重、生活不能自理的患者，巡视时间间隔不超过 1 小时。', '全院', '全体护理人员', '护理部', '林晓梅', '吴文斌', '2024-01-01', '2024-01-01', '2026-11-15', 1, NULL, '医务科 吴文斌：发布（同意）', '已过期，待换版' FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM (SELECT id FROM core_system) AS t WHERE t.id = 3);
INSERT INTO core_system (id, title, system_no, category, level, issuing_authority, version, content, applicable_dept, applicable_personnel, department, drafter, approver, publish_date, effective_date, expiry_date, status, abolish_reason, approval_history, remark) SELECT 4, '危急值报告制度', 'HX-ZD-2025-004', 'SAFETY', 'HOSPITAL', '医务科', 'V1.0', '第一条 危急值是指提示患者处于生命危险状态的检验、检查结果，医技科室发现危急值应立即报告临床科室。\n第二条 接到危急值报告后，临床医师应在 30 分钟内查看患者并处理，处理情况记入病程记录。\n第三条 危急值报告实行登记制度，报告人、接收人、报告时间、处理情况均应记录备查。', '全院', '全体医务人员', '医务科', '李雅琴', NULL, NULL, NULL, NULL, 0, NULL, NULL, '草稿，待发布审批' FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM (SELECT id FROM core_system) AS t WHERE t.id = 4);
INSERT INTO core_system (id, title, system_no, category, level, issuing_authority, version, content, applicable_dept, applicable_personnel, department, drafter, approver, publish_date, effective_date, expiry_date, status, abolish_reason, approval_history, remark) SELECT 5, '抗菌药物分级管理制度', 'HX-ZD-2023-005', 'PHARMACY', 'HOSPITAL', '药剂科', 'V1.0', '第一条 抗菌药物实行分级管理：非限制使用级、限制使用级、特殊使用级。\n第二条 特殊使用级抗菌药物须经药事管理与药物治疗学委员会审核、医务科审批后方可使用。\n第三条 临床药师应当对全院抗菌药物使用情况进行监测，每月汇总上报医务科。', '全院', '全体医务人员', '药剂科', '吴文斌', '吴文斌', '2023-01-01', '2023-01-01', '2025-12-31', 2, '已被新版《抗菌药物分级管理制度》替代', '医务科 吴文斌：发布（同意）；医务科 吴文斌：废止（已被新版《抗菌药物分级管理制度》替代）', '第 1 版已废止' FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM (SELECT id FROM core_system) AS t WHERE t.id = 5);
INSERT INTO core_system (id, title, system_no, category, level, issuing_authority, version, content, applicable_dept, applicable_personnel, department, drafter, approver, publish_date, effective_date, expiry_date, status, abolish_reason, approval_history, remark) SELECT 6, '手术安全核查制度', 'HX-ZD-2024-006', 'MEDICAL', 'DEPT', '医务科', 'V1.0', '第一条 手术安全核查是指在麻醉实施前、手术开始前和患者离开手术室前，由手术医师、麻醉医师和手术室护士共同对患者身份、手术部位、手术方式等进行核查。\n第二条 三方核查应当逐项进行，核查无误后方可进入下一环节，核查记录由三方共同签字确认。\n第三条 对核查中发现的问题，应立即暂停手术进程，核实无误后方可继续。', '手术科室', '全体手术相关医务人员', '医务科', '吴文斌', '陈国强', '2024-06-01', '2024-06-01', '2027-06-30', 1, NULL, '医务科 陈国强：发布（同意）', '科室级制度，手术科室执行' FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM (SELECT id FROM core_system) AS t WHERE t.id = 6);
