INSERT INTO sys_knowledge (id, kb_code, title, category, content, keywords, status, view_count, sort_order, remark) SELECT 1, 'KB-001', '三级医师查房制度要点', '制度规范', '三级医师查房是指主任医师、主治医师、住院医师三级查房。主任医师每周至少查房 1 次，主治医师每日查房，住院医师每日查房并记录。查房内容包括病情评估、诊疗方案、医嘱核查等。', '三级查房,查房制度,核心制度', 1, 0, 1, '' FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM (SELECT id FROM sys_knowledge) AS t WHERE t.id = 1);
INSERT INTO sys_knowledge (id, kb_code, title, category, content, keywords, status, view_count, sort_order, remark) SELECT 2, 'KB-002', '病历书写规范要求', '制度规范', '病历书写应当客观、真实、准确、及时、完整、规范。入院记录应在患者入院后 24 小时内完成，首次病程记录应在患者入院后 8 小时内完成，手术记录应在术后 24 小时内完成。', '病历书写,病历规范,入院记录', 1, 0, 2, '' FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM (SELECT id FROM sys_knowledge) AS t WHERE t.id = 2);
INSERT INTO sys_knowledge (id, kb_code, title, category, content, keywords, status, view_count, sort_order, remark) SELECT 3, 'KB-003', '医师休假申请操作指南', '操作指南', '在休假执业管理页面点击新增，选择申请类型为休假，填写开始与结束日期，系统自动计算天数。提交后先由科主任审批，再由医务科审批，两级通过后生效。', '休假申请,审批流程,操作指南', 1, 0, 3, '' FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM (SELECT id FROM sys_knowledge) AS t WHERE t.id = 3);
INSERT INTO sys_knowledge (id, kb_code, title, category, content, keywords, status, view_count, sort_order, remark) SELECT 4, 'KB-004', '重点授权申请流程', '操作指南', '手术、麻醉、抗肿瘤、精神类重点授权需在线申请，填写授权类型与有效期，提交后科主任与医务科两级审批。授权到期前 30 天系统提醒续期。', '重点授权,处方权,手术授权', 1, 0, 4, '' FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM (SELECT id FROM sys_knowledge) AS t WHERE t.id = 4);
INSERT INTO sys_knowledge (id, kb_code, title, category, content, keywords, status, view_count, sort_order, remark) SELECT 5, 'KB-005', '抗菌药物使用常见问题', '常见问题', '抗菌药物分非限制使用级、限制使用级与特殊使用级。特殊使用级抗菌药物需经抗菌药物管理工作组会诊同意后方可使用。门诊处方抗菌药物使用率应控制在 20% 以内。', '抗菌药物,处方,特殊使用级', 1, 0, 5, '' FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM (SELECT id FROM sys_knowledge) AS t WHERE t.id = 5);
INSERT INTO sys_knowledge (id, kb_code, title, category, content, keywords, status, view_count, sort_order, remark) SELECT 6, 'KB-006', '医疗纠纷防范要点', '法律法规', '医师应严格遵守《医疗纠纷预防和处理条例》，加强医患沟通，规范诊疗行为。发生医疗纠纷后应及时上报医务科，封存病历，妥善保存相关证据，不得涂改、伪造、隐匿病历资料。', '医疗纠纷,医患沟通,病历封存', 1, 0, 6, '' FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM (SELECT id FROM sys_knowledge) AS t WHERE t.id = 6);
INSERT INTO sys_knowledge (id, kb_code, title, category, content, keywords, status, view_count, sort_order, remark) SELECT 7, 'KB-007', '新入职医师培训资料', '培训资料', '新入职医师须完成岗前培训，包括医院规章制度、核心制度、病历书写规范、医院感染防控、医疗安全等内容，考核合格后方可独立执业。', '岗前培训,新入职,核心制度', 1, 0, 7, '' FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM (SELECT id FROM sys_knowledge) AS t WHERE t.id = 7);
INSERT INTO sys_knowledge (id, kb_code, title, category, content, keywords, status, view_count, sort_order, remark) SELECT 8, 'KB-008', '急诊抢救流程规范（旧版）', '其他', '本条为旧版抢救流程，已被新版流程替代，暂作停用处理。', '急诊抢救,旧版,已停用', 0, 0, 8, '旧版内容，已停用' FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM (SELECT id FROM sys_knowledge) AS t WHERE t.id = 8);
