INSERT INTO briefing (id, issue_no, title, template_id, template_name, category, period, content, status, author_name, publish_date, approver, approval_opinion, approval_history, approve_time, reject_reason, remark) SELECT 1, '2026-11-01', '医疗工作简报（2026年11月）', 1, '月度医疗工作简报模板', 'MONTHLY', '2026-11', '工作概况：全院在册医师 12 人；本期工作量登记 8 条，门诊 3420 人次、住院 1066 人次、手术 241 台。医疗质量：本期检查计划 4 个（已完成 1 个、进行中 1 个），检查记录 3 条、平均分 80.33 分；发现问题 4 个，其中严重问题 2 个。会诊与新技术：本期 MDT 会诊申请 5 例（已通过 2 例，其中紧急会诊 2 例）；新技术、新项目申报 3 项（已立项 1 项、已推广 0 项）。医师考核：本年度考核 6 人次，平均分 81.17 分，优秀 2 人。下月计划：下月重点工作请结合本期情况手工补充。', 2, '医务科', '2026-11-22', '吴文斌', '同意发布', '医务科 吴文斌：通过（同意发布）', '2026-11-22 10:00:00', NULL, '' FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM (SELECT id FROM briefing) AS t WHERE t.id = 1);
INSERT INTO briefing (id, issue_no, title, template_id, template_name, category, period, content, status, author_name, publish_date, approver, approval_opinion, approval_history, approve_time, reject_reason, remark) SELECT 2, '2026-11-02', '医疗工作简报（2026年11月·第2期）', 1, '月度医疗工作简报模板', 'MONTHLY', '2026-11', '工作概况：本期为 11 月第 2 期简报，补充刊发各科室工作动态与上周检查整改进展。', 1, '医务科', NULL, NULL, NULL, NULL, NULL, NULL, '' FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM (SELECT id FROM briefing) AS t WHERE t.id = 2);
INSERT INTO briefing (id, issue_no, title, template_id, template_name, category, period, content, status, author_name, publish_date, approver, approval_opinion, approval_history, approve_time, reject_reason, remark) SELECT 3, '2026-10-01', '医疗工作简报（2026年10月）', 1, '月度医疗工作简报模板', 'MONTHLY', '2026-10', '工作概况：10 月全院工作平稳有序，门诊与住院量保持稳定。医疗质量：本期检查计划 3 个，检查记录 2 条，平均分 82.50 分；发现问题 3 个，其中严重问题 1 个。', 2, '医务科', '2026-10-25', '吴文斌', '同意发布', '医务科 吴文斌：通过（同意发布）', '2026-10-25 09:30:00', NULL, '' FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM (SELECT id FROM briefing) AS t WHERE t.id = 3);
